import { useMediaQuery } from "../useMediaQuery/index.mjs";
//#region src/usePreferredColorScheme/index.ts
const usePreferredColorScheme = (defaultState = "no-preference") => {
	const isLight = useMediaQuery("(prefers-color-scheme: light)", false);
	return useMediaQuery("(prefers-color-scheme: dark)", false) ? "dark" : isLight ? "light" : defaultState;
};
//#endregion
export { usePreferredColorScheme };
